96:     private void executeSchedulingTest(Configuration configuration) throws Exception {
97:         final long slotIdleTimeout = 50L;
98:         configuration.set(JobManagerOptions.SLOT_IDLE_TIMEOUT, slotIdleTimeout);
99: 
100:         configuration.set(TaskManagerOptions.TOTAL_FLINK_MEMORY, MemorySize.parse("1g"));
101: 
102:         final int parallelism = 4;
103:         final MiniClusterConfiguration miniClusterConfiguration =
104:                 new MiniClusterConfiguration.Builder()
105:                         .withRandomPorts()
106:                         .setConfiguration(configuration)
107:                         .setNumTaskManagers(parallelism)
108:                         .setNumSlotsPerTaskManager(1)
109:                         .build();
110: 
111:         try (MiniCluster miniCluster = new MiniCluster(miniClusterConfiguration)) {
112:             miniCluster.start();
113: 
114:             MiniClusterClient miniClusterClient = new MiniClusterClient(configuration, miniCluster);
115: 
116:             JobGraph jobGraph = createJobGraph(slotIdleTimeout << 1, parallelism);
117: 
118:             // wait for the submission to succeed
119:             JobID jobID = miniClusterClient.submitJob(jobGraph).get();
120: 
121:             CompletableFuture<JobResult> resultFuture = miniClusterClient.requestJobResult(jobID);
