145: 
146:         ExecutionConfig executionConfig = new ExecutionConfig();
147:         executionConfig.setRestartStrategy(RestartStrategies.fixedDelayRestart(1, delay));
148: 
149:         return JobGraphBuilder.newStreamingJobGraphBuilder()
