539:     /** Due to canonicalization, paths need to be renormalized before comparison. */
540:     private static class NormalizedPathMatcher extends TypeSafeMatcher<Path> {
541: 
542:         private final Path reNormalizedExpected;
543: 
544:         private NormalizedPathMatcher(Path expected) {
545:             this.reNormalizedExpected = expected == null ? null : new Path(expected.toString());
546:         }
547: 
548:         @Override
549:         protected boolean matchesSafely(Path actual) {
550:             if (reNormalizedExpected == null) {
551:                 return actual == null;
552:             }
553: 
554:             Path reNormalizedActual = new Path(actual.toString());
555:             return reNormalizedExpected.equals(reNormalizedActual);
556:         }
557: 
558:         @Override
559:         public void describeTo(Description description) {
560:             description.appendValue(reNormalizedExpected);
561:         }
562:     }
