390:             }
391:             String name = "Unknown Call Name";
392:             try {
393:                 while (!hasCaughtUp) {
394:                     while (!pendingCalls.isEmpty()) {
395:                         NamedCall namedCall = pendingCalls.poll();
396:                         if (namedCall != null) {
397:                             name = namedCall.name;
398:                             namedCall.getConsumer().accept(internalCoordinator);
399:                         }
400:                     }
401:                     synchronized (this) {
402:                         // We need to check the pending calls queue again in case a new
403:                         // pending call is added after we process the last one and before
404:                         // we grab the lock.
405:                         if (pendingCalls.isEmpty()) {
406:                             hasCaughtUp = true;
407:                         }
408:                     }
409:                 }
410:             } catch (Throwable t) {
411:                 LOG.error("Failed to process pending calls {} on coordinator.", name, t);
412:                 cleanAndFailJob(t);
413:             }
414:         }
415: 
416:         void start() throws Exception {
417:             internalCoordinator.start();
418:         }
419: 
420:         void resetAndStart(
421:                 final long checkpointId,
422:                 @Nullable final byte[] checkpointData,
423:                 final boolean started) {
424: 
425:             if (failed || closed || internalCoordinator == null) {
426:                 return;
427:             }
428:             try {
429:                 internalCoordinator.resetToCheckpoint(checkpointId, checkpointData);
430:                 // Start the new coordinator if this coordinator has been started before reset to
431:                 // the checkpoint.
432:                 if (started) {
433:                     internalCoordinator.start();
434:                 }
435:             } catch (Exception e) {
436:                 LOG.error("Failed to reset the coordinator to checkpoint and start.", e);
437:                 cleanAndFailJob(e);
438:             }
439:         }
440: 
441:         private void cleanAndFailJob(Throwable t) {
442:             // Don't repeatedly fail the job.
443:             if (!failed) {
444:                 failed = true;
445:                 internalQuiesceableContext.getContext().failJob(t);
446:                 pendingCalls.clear();
447:             }
448:         }
449:     }
450: 
451:     private static class NamedCall {
452:         private final String name;
453:         private final ThrowingConsumer<OperatorCoordinator, ?> consumer;
454: 
455:         private NamedCall(String name, ThrowingConsumer<OperatorCoordinator, ?> consumer) {
456:             this.name = name;
457:             this.consumer = consumer;
458:         }
459: 
460:         public String getName() {
461:             return name;
462:         }
463: 
464:         public ThrowingConsumer<OperatorCoordinator, ?> getConsumer() {
465:             return consumer;
466:         }
467:     }
468: }
